import * as Phaser from "phaser";
import { ASSET_KEYS } from "../common/assets";
import { type DataManager } from "../common/data-manager";
import { CUSTOM_EVENTS, EVENT_BUS } from "../common/event-bus";
import { type Keyboard } from "../components/keyboard";
import { SCENE_KEYS } from "./scene-keys";

const GRID_SIZE = 10;
const MINE_MAX_HEALTH = 24;
const CRACK_WIDTH = 48;
const STEPS_PER_TILE = 6;
const IRON_TARGET_PERCENTAGE = 0.15;
const GEM_COUNT = 1; // Number of gems to place

const IRONS: { size: [number, number]; covered: number; irons: number[][] }[] =
  [
    { size: [32, 128], covered: 4, irons: [[1], [1], [1], [1]] },
    {
      size: [64, 128],
      covered: 8,
      irons: [
        [1, 1],
        [1, 1],
        [1, 1],
        [1, 1],
      ],
    },
    {
      size: [128, 64],
      covered: 8,
      irons: [
        [1, 1, 1, 1],
        [1, 1, 1, 1],
      ],
    },
    { size: [128, 32], covered: 4, irons: [[1, 1, 1, 1]] },
    {
      size: [96, 96],
      covered: 9,
      irons: [
        [1, 1, 1],
        [1, 1, 1],
        [1, 1, 1],
      ],
    },
    {
      size: [64, 64],
      covered: 4,
      irons: [
        [1, 1],
        [1, 1],
      ],
    },
    {
      size: [64, 96],
      covered: 4,
      irons: [
        [1, 0],
        [1, 1],
        [0, 1],
      ],
    },
    {
      size: [64, 96],
      covered: 4,
      irons: [
        [0, 1],
        [1, 1],
        [1, 0],
      ],
    },
    {
      size: [96, 64],
      covered: 4,
      irons: [
        [1, 1, 0],
        [0, 1, 1],
      ],
    },
    {
      size: [96, 64],
      covered: 4,
      irons: [
        [0, 1, 1],
        [1, 1, 0],
      ],
    },
    {
      size: [96, 64],
      covered: 4,
      irons: [
        [0, 1, 0],
        [1, 1, 1],
      ],
    },
    {
      size: [96, 64],
      covered: 4,
      irons: [
        [1, 1, 1],
        [0, 1, 0],
      ],
    },
    {
      size: [64, 96],
      covered: 4,
      irons: [
        [1, 0],
        [1, 1],
        [1, 0],
      ],
    },
    {
      size: [64, 96],
      covered: 4,
      irons: [
        [0, 1],
        [1, 1],
        [0, 1],
      ],
    },
  ];

enum TileState {
  BACKGROUND = 0, // 6 damage
  DIRT_WITH_CRACK = 1, // 5 damage
  DIRT_WITH_ROCKS = 2, // 4 damage
  STONE_WITH_CRACK = 3, // 3 damage
  ONE_ROCK = 4, // 2 damage
  TWO_ROCKS = 5, // 1 damage
  LARGE_ROCK = 6, // Undamaged
}

enum Tool {
  PICKAXE = 0,
  HAMMER = 1,
}

const VALID_STARTING_STATES = [
  TileState.LARGE_ROCK,
  TileState.ONE_ROCK,
  TileState.DIRT_WITH_ROCKS,
];

type GridTile = {
  sprite: Phaser.GameObjects.Sprite;
  state: TileState;
  hasGem: boolean;
  hasIron: boolean;
  ironIndex?: number; // Index into IRONS array
  ironSprite?: Phaser.GameObjects.Image;
  ironGroup?: {
    tiles: GridTile[];
    sprite: Phaser.GameObjects.Image;
  };
  gemGroup?: {
    tiles: GridTile[];
    sprite?: Phaser.GameObjects.Image;
    collected?: boolean;
  };
  x: number;
  y: number;
};

export class MiningMinigameScene extends Phaser.Scene {
  private grid: GridTile[][] = [];
  private dataManager!: DataManager;
  private selectedTool: Tool = Tool.PICKAXE;
  private mineHealth: number = MINE_MAX_HEALTH;
  private gameRunning = true;
  private miningSpotId?: number; // Track which mining spot this game is for
  private gemFrame?: string;
  private ironGroups: {
    tiles: GridTile[];
    sprite: Phaser.GameObjects.Image;
  }[] = [];

  private gemGroups: {
    tiles: GridTile[];
    sprite?: Phaser.GameObjects.Image;
    collected?: boolean;
  }[] = [];

  // Cursor navigation
  private cursorX = 0;
  private cursorY = 0;
  private cursor!: Phaser.GameObjects.Sprite;
  private keyboard!: Keyboard;

  // Tool animation sprites
  private toolSprite!: Phaser.GameObjects.Sprite;
  private hitSprite!: Phaser.GameObjects.Sprite;

  // Timer references for cleanup
  private activeTimers: Phaser.Time.TimerEvent[] = [];

  // UI Elements
  private backgroundImage!: Phaser.GameObjects.Image;
  private pickaxeIcon!: Phaser.GameObjects.Sprite;
  private hammerIcon!: Phaser.GameObjects.Sprite;
  private cracks: Phaser.GameObjects.Image[] = [];

  constructor() {
    super(SCENE_KEYS.MINING_MINIGAME_SCENE);
  }

  init(data: {
    miningSpotId?: number;
    dataManager: DataManager;
    gemFrame: string;
    keyboard: Keyboard;
  }): void {
    this.miningSpotId = data.miningSpotId;
    this.dataManager = data.dataManager;
    this.gemFrame = data.gemFrame;
    this.keyboard = data.keyboard;
  }

  create(): void {
    // Reset game state for fresh start
    this.grid = [];
    this.selectedTool = Tool.PICKAXE;
    this.mineHealth = MINE_MAX_HEALTH;
    this.gameRunning = true;
    this.ironGroups = [];
    this.cursorX = 0;
    this.cursorY = 0;
    this.cracks = [];
    this.activeTimers = [];

    this.setupUI();
    this.createGrid();
    this.createCursor();
    this.createAnimationSprites();
    this.placeRandomGems();
    this.placeRandomIron();
    this.updateToolSelection();
    this.updateHealthDisplay();
  }

  public override update(): void {
    if (!this.gameRunning) {
      return;
    }

    if (this.keyboard.isUpJustDown) {
      this.moveCursor(0, -1);
    }

    if (this.keyboard.isLeftJustDown) {
      this.moveCursor(-1, 0);
    }

    if (this.keyboard.isDownJustDown) {
      this.moveCursor(0, 1);
    }

    if (this.keyboard.isRightJustDown) {
      this.moveCursor(1, 0);
    }

    if (this.keyboard.isActionKeyJustDown || this.keyboard.isEnterKeyJustDown) {
      this.digAtCursor();
    }

    if (this.keyboard.isUseJustDown) {
      this.selectedTool =
        this.selectedTool === Tool.PICKAXE ? Tool.HAMMER : Tool.PICKAXE;
      this.updateToolSelection();
    }

    if (this.keyboard.isEscapeJustDown) {
      this.exitGame();
    }
  }

  private setupUI(): void {
    const camera = this.cameras.main;
    const width = camera.width;
    const height = camera.height;
    const centerX = camera.centerX;
    const centerY = camera.centerY;

    // Background - scale to fill entire screen
    this.backgroundImage = this.add.image(
      centerX,
      centerY,
      ASSET_KEYS.MINING_BG,
    );
    this.backgroundImage.setScrollFactor(0); // Fix to camera
    this.backgroundImage.setDepth(-10); // Furthest back
    // Scale to cover entire screen
    const scaleX = width / this.backgroundImage.width;
    const scaleY = height / this.backgroundImage.height;
    if (scaleX !== scaleY) {
      throw new Error("expected x and y scale factors to be equal");
    }
    this.backgroundImage.setScale(scaleX);

    // Tool icons - position at right side of screen
    this.pickaxeIcon = this.add.sprite(
      width - 40,
      136,
      ASSET_KEYS.MINING_TOOLICONS,
      "pick_unselected.png",
    );
    this.pickaxeIcon.setScrollFactor(0); // Fix to camera

    this.hammerIcon = this.add.sprite(
      width - 40,
      244,
      ASSET_KEYS.MINING_TOOLICONS,
      "hammer_unselected.png",
    );
    this.hammerIcon.setScrollFactor(0); // Fix to camera

    this.add.text(width - 70, 307, "Switch\nE", {
      align: "center",
      fontSize: "20px",
      fontFamily: "Ubuntu Sans",
    });
  }

  private createGrid(): void {
    const camera = this.cameras.main;
    const startX = 0;
    const startY = 80;

    const gridWidth = camera.width - startX;
    const gridHeight = camera.height - startY;

    const tileSize = Math.min(gridWidth / GRID_SIZE, gridHeight / GRID_SIZE);

    for (let row = 0; row < GRID_SIZE; row++) {
      this.grid[row] = [];
      for (let col = 0; col < GRID_SIZE; col++) {
        const x = startX + col * tileSize;
        const y = startY + row * tileSize;

        const startingState =
          VALID_STARTING_STATES[
            Math.floor(Math.random() * VALID_STARTING_STATES.length)
          ];

        const tileSprite = this.add.sprite(
          x + tileSize / 2,
          y + tileSize / 2,
          ASSET_KEYS.MINING_TILES,
          `tiles ${startingState - 1}.png`,
        );
        tileSprite.setInteractive();
        tileSprite.setScrollFactor(0); // Fix to camera
        tileSprite.setDisplaySize(tileSize, tileSize); // Scale to larger size
        tileSprite.setDepth(0); // Front layer to cover iron/gems

        const tile: GridTile = {
          sprite: tileSprite,
          state: startingState,
          hasGem: false,
          hasIron: false,
          x: col,
          y: row,
        };

        this.grid[row][col] = tile;
      }
    }
  }

  private createCursor(): void {
    // Create cursor sprite using the cursor asset
    this.cursor = this.add.sprite(0, 0, ASSET_KEYS.MINING_CURSOR);
    this.cursor.setScrollFactor(0); // Fix to camera
    this.cursor.setDepth(10); // Ensure cursor appears above iron and gems

    // Start cursor at center of grid
    this.cursorX = 0;
    this.cursorY = 0;
    this.updateCursorPosition();
  }

  private createAnimationSprites(): void {
    // Create tool animation sprite (initially hidden)
    this.toolSprite = this.add.sprite(0, 0, ASSET_KEYS.MINING_TOOLS);
    this.toolSprite.setScrollFactor(0);
    this.toolSprite.setVisible(false);
    this.toolSprite.setDepth(15); // Above cursor

    // Create hit animation sprite (initially hidden)
    this.hitSprite = this.add.sprite(0, 0, ASSET_KEYS.MINING_HITS);
    this.hitSprite.setScrollFactor(0);
    this.hitSprite.setVisible(false);
    this.hitSprite.setDepth(15); // Above cursor
  }

  private updateCursorPosition(): void {
    // Position cursor on the selected tile
    const selectedTile = this.grid[this.cursorY][this.cursorX];
    if (selectedTile) {
      this.cursor.setPosition(selectedTile.sprite.x, selectedTile.sprite.y);

      // Scale cursor to be slightly larger than the tile to create a border effect
      const tileSize = selectedTile.sprite.displayWidth;
      // Not entirely sure where 12 comes from, but it's the minimum value for the indicator to not
      // overlap the highlighted tile.
      const cursorSize = tileSize + 12;
      this.cursor.setDisplaySize(cursorSize, cursorSize);
    }
  }

  private moveCursor(deltaX: number, deltaY: number): void {
    if (!this.gameRunning) {
      return;
    }

    // Calculate new position
    const newX = this.cursorX + deltaX;
    const newY = this.cursorY + deltaY;

    // Clamp to grid bounds
    if (newX >= 0 && newX < GRID_SIZE && newY >= 0 && newY < GRID_SIZE) {
      this.cursorX = newX;
      this.cursorY = newY;
      this.updateCursorPosition();
    }
  }

  private digAtCursor(): void {
    if (!this.gameRunning) {
      return;
    }

    const selectedTile = this.grid[this.cursorY][this.cursorX];
    if (selectedTile) {
      this.onTileClick(selectedTile);
    }
  }

  private placeRandomGems(): void {
    const occupiedTiles = new Set<string>();

    // First, mark all iron tiles as occupied
    this.ironGroups.forEach((ironGroup) => {
      ironGroup.tiles.forEach((tile) => {
        occupiedTiles.add(`${tile.y},${tile.x}`);
      });
    });

    for (let i = 0; i < GEM_COUNT; i++) {
      let placed = false;

      while (!placed) {
        // Gems are 2x2 tiles (64x64 pixels / 32 pixels per tile)
        const startCol = Phaser.Math.Between(0, GRID_SIZE - 2);
        const startRow = Phaser.Math.Between(0, GRID_SIZE - 2);

        // Check if this 2x2 area is available
        let canPlace = true;
        for (let row = startRow; row < startRow + 2 && canPlace; row++) {
          for (let col = startCol; col < startCol + 2 && canPlace; col++) {
            if (occupiedTiles.has(`${row},${col}`)) {
              canPlace = false;
            }
          }
        }

        if (canPlace) {
          this.createGemGroup(startRow, startCol);

          // Mark all tiles in this 2x2 area as occupied
          for (let row = startRow; row < startRow + 2; row++) {
            for (let col = startCol; col < startCol + 2; col++) {
              occupiedTiles.add(`${row},${col}`);
            }
          }
          placed = true;
        }
      }
    }
  }

  private createGemGroup(startRow: number, startCol: number): void {
    const tiles: GridTile[] = [];

    // Link 2x2 tiles to gem group
    for (let row = startRow; row < startRow + 2; row++) {
      for (let col = startCol; col < startCol + 2; col++) {
        const tile = this.grid[row][col];
        tile.hasGem = true;
        tiles.push(tile);
      }
    }

    const gemGroup = {
      tiles,
      sprite: undefined,
      collected: false,
    };

    // Link tiles to group
    tiles.forEach((tile) => {
      tile.gemGroup = gemGroup;
    });

    // Add to gems tracking array
    this.gemGroups.push(gemGroup);
  }

  private placeRandomIron(): void {
    const totalTiles = GRID_SIZE * GRID_SIZE;
    const targetTilesCovered = Math.round(totalTiles * IRON_TARGET_PERCENTAGE);
    const occupiedTiles = new Set<string>();
    let tilesCovered = 0;

    while (tilesCovered < targetTilesCovered) {
      const ironIndex = Phaser.Math.Between(0, IRONS.length - 1);
      const ironInfo = IRONS[ironIndex];
      const [ironPixelWidth, ironPixelHeight] = ironInfo.size;
      const tilesWide = ironPixelWidth / 32;
      const tilesHigh = ironPixelHeight / 32;

      // Don't place iron if it would exceed our target
      if (tilesCovered + ironInfo.covered > targetTilesCovered) {
        // Try to find a smaller iron that fits
        let foundSmallerIron = false;
        for (let i = 0; i < IRONS.length; i++) {
          if (IRONS[i].covered <= targetTilesCovered - tilesCovered) {
            const smallerIronInfo = IRONS[i];
            const [smallerWidth, smallerHeight] = smallerIronInfo.size;
            const smallerTilesWide = smallerWidth / 32;
            const smallerTilesHigh = smallerHeight / 32;

            if (
              this.tryPlaceIron(
                i,
                smallerTilesWide,
                smallerTilesHigh,
                occupiedTiles,
              )
            ) {
              tilesCovered += smallerIronInfo.covered;
              foundSmallerIron = true;
              break;
            }
          }
        }
        if (!foundSmallerIron) break;
        continue;
      }

      // Try to place this iron
      if (this.tryPlaceIron(ironIndex, tilesWide, tilesHigh, occupiedTiles)) {
        tilesCovered += ironInfo.covered;
      } else {
        // If we can't place any more irons, break
        break;
      }
    }
  }

  private tryPlaceIron(
    ironIndex: number,
    tilesWide: number,
    tilesHigh: number,
    occupiedTiles: Set<string>,
  ): boolean {
    let attempts = 0;

    while (attempts < 50) {
      const startCol = Phaser.Math.Between(0, GRID_SIZE - tilesWide);
      const startRow = Phaser.Math.Between(0, GRID_SIZE - tilesHigh);

      // Check if this area is available
      let canPlace = true;
      for (let row = startRow; row < startRow + tilesHigh && canPlace; row++) {
        for (
          let col = startCol;
          col < startCol + tilesWide && canPlace;
          col++
        ) {
          if (
            occupiedTiles.has(`${row},${col}`) ||
            this.grid[row][col].hasGem
          ) {
            canPlace = false;
          }
        }
      }

      if (canPlace) {
        this.createIronGroup(
          startRow,
          startCol,
          tilesWide,
          tilesHigh,
          ironIndex,
        );

        // Mark all tiles in this area as occupied
        for (let row = startRow; row < startRow + tilesHigh; row++) {
          for (let col = startCol; col < startCol + tilesWide; col++) {
            occupiedTiles.add(`${row},${col}`);
          }
        }
        return true;
      }
      attempts++;
    }
    return false;
  }

  private createIronGroup(
    startRow: number,
    startCol: number,
    tilesWide: number,
    tilesHigh: number,
    ironIndex: number,
  ): void {
    const tileSize = this.grid[0][0].sprite.displayWidth;
    const ironAssetKey = `MINING_IRON_${ironIndex}` as keyof typeof ASSET_KEYS;

    // Calculate iron position and size
    const displayWidth = tilesWide * tileSize;
    const displayHeight = tilesHigh * tileSize;

    // Position iron at the center of its area
    const centerX =
      this.grid[startRow][startCol].sprite.x + ((tilesWide - 1) * tileSize) / 2;
    const centerY =
      this.grid[startRow][startCol].sprite.y + ((tilesHigh - 1) * tileSize) / 2;

    // Create iron sprite - initially hidden
    const ironSprite = this.add.image(
      centerX,
      centerY,
      ASSET_KEYS[ironAssetKey],
    );
    ironSprite.setScrollFactor(0);
    ironSprite.setDisplaySize(displayWidth, displayHeight);
    ironSprite.setDepth(-5); // Between background and tiles
    ironSprite.setVisible(true); // Always visible, but covered by tiles until dug

    // Create iron group and link tiles based on iron pattern
    const tiles: GridTile[] = [];
    const ironPattern = IRONS[ironIndex].irons;

    for (let row = startRow; row < startRow + tilesHigh; row++) {
      for (let col = startCol; col < startCol + tilesWide; col++) {
        const tile = this.grid[row][col];
        const patternRow = row - startRow;
        const patternCol = col - startCol;

        // Only mark as iron if pattern indicates iron at this position
        if (ironPattern[patternRow][patternCol] === 1) {
          tile.hasIron = true;
          tile.ironIndex = ironIndex;
        }

        tiles.push(tile);
      }
    }

    const ironGroup = { tiles, sprite: ironSprite };
    this.ironGroups.push(ironGroup);

    // Link tiles to group
    tiles.forEach((tile) => {
      tile.ironGroup = ironGroup;
    });
  }

  private onTileClick(tile: GridTile): void {
    if (!this.gameRunning || tile.state === TileState.BACKGROUND) {
      return;
    }

    // Show tool and hit animations
    this.playMiningAnimation(tile);

    let won: boolean;
    // Normal digging behavior for all tiles
    if (this.selectedTool === Tool.PICKAXE) {
      won = this.digWithPickaxe(tile);
    } else {
      won = this.digWithHammer(tile);
    }

    if (!won) {
      this.updateHealthDisplay();
      this.checkGameOver();
    }
  }

  private playMiningAnimation(tile: GridTile): void {
    // Position both sprites at the clicked tile
    const tileX = tile.sprite.x;
    const tileY = tile.sprite.y;
    const tileSize = tile.sprite.displayWidth;

    // Determine hit frame - only show iron hit if tile will be dug to background and has iron
    let hitFrame: string;
    const damage = 2;
    const willReachBackground =
      (Math.max(tile.state - damage, TileState.BACKGROUND) as TileState) ===
      TileState.BACKGROUND;

    if (willReachBackground && tile.hasIron) {
      hitFrame = "hits 2.png"; // Iron hit effect when reaching background with iron
    } else if (this.selectedTool === Tool.PICKAXE) {
      hitFrame = "hits 0.png"; // Normal pickaxe hit
    } else {
      hitFrame = "hits 1.png"; // Normal hammer hit
    }

    // Show and position tool sprite with proper animation sequence
    this.toolSprite.setPosition(tileX + tileSize / 2, tileY);
    this.toolSprite.setDisplaySize(tileSize * 2, tileSize * 2); // Make tool larger but not too big
    this.toolSprite.setVisible(true);

    // Animate tool swing with faster frame sequence
    if (this.selectedTool === Tool.PICKAXE) {
      this.animateToolSwing(
        "tools 0.png",
        "tools 1.png",
        hitFrame,
        tileX,
        tileY,
      );
    } else {
      this.animateToolSwing(
        "tools 2.png",
        "tools 3.png",
        hitFrame,
        tileX,
        tileY,
      );
    }

    // Hide hit sprite after showing it
    const timer3 = this.time.delayedCall(270, () => {
      // 120ms tool + 150ms hit display
      this.hitSprite.setVisible(false);
    });
    this.activeTimers.push(timer3);
  }

  private animateToolSwing(
    frame1: string,
    frame2: string,
    hitFrame: string,
    hitX: number,
    hitY: number,
  ): void {
    // Tool animation: frame1 -> frame2 -> hide
    this.toolSprite.setFrame(frame1);
    const timer1 = this.time.delayedCall(60, () => {
      this.toolSprite.setFrame(frame2);
    });
    const timer2 = this.time.delayedCall(120, () => {
      this.toolSprite.setVisible(false);
      // Show hit effect after tool animation completes
      this.hitSprite.setFrame(hitFrame);
      this.hitSprite.setPosition(hitX, hitY);
      this.hitSprite.setVisible(true);
    });
    this.activeTimers.push(timer1, timer2);
  }

  private digWithPickaxe(centerTile: GridTile): boolean {
    // Pickaxe affects a + pattern with different damage levels
    const { x, y } = centerTile;

    let won = false;

    // Center gets 2 damage
    won ||= this.damageTile(centerTile, 2);

    // Cardinal directions get 1 damage
    won ||= this.damageTileAt(x - 1, y, 1); // left
    won ||= this.damageTileAt(x + 1, y, 1); // right
    won ||= this.damageTileAt(x, y - 1, 1); // up
    won ||= this.damageTileAt(x, y + 1, 1); // down

    this.mineHealth -= 1;
    return won;
  }

  private digWithHammer(centerTile: GridTile): boolean {
    // Hammer affects a 3x3 area with different damage patterns
    const { x, y } = centerTile;

    let won = false;
    // Center and + pattern get 2 damage
    won ||= this.damageTile(centerTile, 2);
    won ||= this.damageTileAt(x - 1, y, 2); // left
    won ||= this.damageTileAt(x + 1, y, 2); // right
    won ||= this.damageTileAt(x, y - 1, 2); // up
    won ||= this.damageTileAt(x, y + 1, 2); // down

    // Diagonal corners get 1 damage
    won ||= this.damageTileAt(x - 1, y - 1, 1); // top-left
    won ||= this.damageTileAt(x + 1, y - 1, 1); // top-right
    won ||= this.damageTileAt(x - 1, y + 1, 1); // bottom-left
    won ||= this.damageTileAt(x + 1, y + 1, 1); // bottom-right

    this.mineHealth -= 2;
    return won;
  }

  private damageTileAt(x: number, y: number, damage: number): boolean {
    if (x >= 0 && x < GRID_SIZE && y >= 0 && y < GRID_SIZE) {
      return this.damageTile(this.grid[y][x], damage);
    }

    return false;
  }

  private damageTile(tile: GridTile, damage: number): boolean {
    if (tile.state === TileState.BACKGROUND) {
      return false;
    }

    // Subtract damage since we're going from SOLID (5) down to BACKGROUND (0)
    const newState: TileState = Math.max(
      tile.state - damage,
      TileState.BACKGROUND,
    );

    tile.state = newState;

    if (newState === TileState.BACKGROUND) {
      // Tile is completely dug out - make it invisible
      tile.sprite.setVisible(false);
    } else {
      // Show appropriate crack state - map enum values to frame numbers
      tile.sprite.setFrame(`tiles ${newState - 1}.png`);
    }

    // Check gem reveal whenever any gem tile is damaged
    if (tile.hasGem && tile.gemGroup) {
      return this.checkGemReveal(tile.gemGroup);
    }

    return false;
  }

  private checkGemReveal(gemGroup: {
    tiles: GridTile[];
    sprite?: Phaser.GameObjects.Image;
    collected?: boolean;
  }): boolean {
    // Create gem sprite if not already created
    if (!gemGroup.sprite) {
      this.createGemSprite(gemGroup);
    }

    // Show gem when any tile is dug (not background)
    const anyDug = gemGroup.tiles.some(
      (tile) => tile.state < TileState.LARGE_ROCK,
    );
    if (anyDug && gemGroup.sprite) {
      gemGroup.sprite.setVisible(true);
    }

    // Check if all 4 tiles are fully dug for collection
    const allDug = gemGroup.tiles.every(
      (tile) => tile.state === TileState.BACKGROUND,
    );

    if (allDug && !gemGroup.collected) {
      this.collectGem(gemGroup);
      return true;
    }

    return false;
  }

  private createGemSprite(gemGroup: {
    tiles: GridTile[];
    sprite?: Phaser.GameObjects.Image;
    collected?: boolean;
  }): void {
    if (gemGroup.sprite) return; // Already created

    // Calculate center position of 2x2 gem area
    const topLeftTile = gemGroup.tiles[0];
    const tileSize = topLeftTile.sprite.displayWidth;
    const centerX = topLeftTile.sprite.x + tileSize / 2;
    const centerY = topLeftTile.sprite.y + tileSize / 2;

    // Create gem sprite (2x2 tiles = 2 * tileSize)
    const gemSprite = this.add.image(
      centerX,
      centerY,
      ASSET_KEYS.MINING_GEMS,
      this.gemFrame,
    );
    gemSprite.setScrollFactor(0);
    gemSprite.setDisplaySize(tileSize * 2, tileSize * 2);
    gemSprite.setDepth(-5); // Between background and tiles
    gemSprite.setVisible(false); // Initially hidden until any tile is dug

    gemGroup.sprite = gemSprite;
  }

  private collectGem(gemGroup: {
    tiles: GridTile[];
    sprite?: Phaser.GameObjects.Image;
    collected?: boolean;
  }): void {
    if (!gemGroup.sprite || gemGroup.collected) return; // Gem not revealed or already collected

    // Mark as collected
    gemGroup.collected = true;

    // Set frontend flag to indicate gem is collected for this mining spot
    if (this.miningSpotId !== undefined) {
      const gemCollectedFlag = `mining_${this.miningSpotId}_gem_collected`;
      this.dataManager.setFrontendFlag(gemCollectedFlag, "true");
    }

    this.endGameWithSuccess();
  }

  private updateToolSelection(): void {
    if (this.selectedTool === Tool.PICKAXE) {
      this.pickaxeIcon.setFrame("pick_selected.png");
      this.hammerIcon.setFrame("hammer_unselected.png");
      this.cursor.setFrame("blue.png");
    } else {
      this.pickaxeIcon.setFrame("pick_unselected.png");
      this.hammerIcon.setFrame("hammer_selected.png");
      this.cursor.setFrame("red.png");
    }
  }

  private updateHealthDisplay(): void {
    const y = 44;

    const totalSteps = (this.cameras.main.width / CRACK_WIDTH) * STEPS_PER_TILE;
    if (MINE_MAX_HEALTH > totalSteps) {
      throw new Error(
        "not enough space on the screen to display the full mine health",
      );
    }
    const damage = Math.floor(
      totalSteps - this.mineHealth * (totalSteps / MINE_MAX_HEALTH),
    );
    const crackFull = "crack_full.png";

    const getFrame = (i: number): string => {
      if ((i + 1) * STEPS_PER_TILE < damage) {
        return crackFull;
      } else {
        const health = damage - i * STEPS_PER_TILE;
        return `crack ${health}.png`;
      }
    };

    const getX = (i: number): number => {
      const frame = getFrame(i);
      let offset: number;
      if (frame === crackFull) {
        offset = i * CRACK_WIDTH;
      } else {
        offset = (i + 1) * CRACK_WIDTH;
      }

      return this.cameras.main.width - offset;
    };

    for (let i = 0; i < this.cracks.length; i++) {
      this.cracks[i].setFrame(getFrame(i));
      this.cracks[i].setX(getX(i));
    }

    while (this.cracks.length * STEPS_PER_TILE < damage) {
      this.cracks.push(
        this.add.image(
          getX(this.cracks.length),
          y,
          ASSET_KEYS.MINING_CRACKS,
          getFrame(this.cracks.length),
        ),
      );
    }
  }

  private checkGameOver(): void {
    if (this.mineHealth <= 0) {
      this.gameRunning = false;

      EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
        messages: ["Game over. You weren't able to find the gem."],
        choices: [],
      });
      EVENT_BUS.once(CUSTOM_EVENTS.DIALOG_COMPLETE, () => {
        this.exitGame();
      });
    }
  }

  private endGameWithSuccess(): void {
    this.gameRunning = false;
    // Complete the mining quest
    this.completeMiningQuest();

    EVENT_BUS.emit(CUSTOM_EVENTS.DIALOG_START, {
      messages: [
        "You found the gem! Give it to the Puzzmon who requested it to complete the quest.",
      ],
      choices: [],
    });
    EVENT_BUS.once(CUSTOM_EVENTS.DIALOG_COMPLETE, () => {
      this.exitGame();
    });
  }

  private completeMiningQuest(): void {
    // Set flag to complete the mining quest for this specific spot and unlock puzzle
    if (this.dataManager && this.miningSpotId !== undefined) {
      const questFlag = `serpentine_mining_quest_${this.miningSpotId}`;
      const questCompleteFlag = `mining_${this.miningSpotId}_quest_complete`;

      // Set story flag for backend persistence
      this.dataManager.setFlagValue(questFlag, "completed");
      this.dataManager.completeInteraction(questFlag);

      // Set frontend flag for NPC dialogue change
      this.dataManager.setFrontendFlag(questCompleteFlag, "true");
    }
  }

  private exitGame(): void {
    this.cleanupTimers();
    this.scene.stop();
    EVENT_BUS.emit(CUSTOM_EVENTS.MINING_MINI_GAME_COMPLETE);
  }

  private cleanupTimers(): void {
    // Cancel all active timers to prevent callbacks after scene exit
    this.activeTimers.forEach((timer) => {
      if (timer) {
        timer.destroy();
      }
    });
    this.activeTimers = [];
  }

  destroy(): void {
    this.cleanupTimers();
  }
}
