import * as Phaser from "phaser";
import type { TiledPlatformObject } from "../../common/tiled/types";
import type { CustomObject, Direction } from "../../common/types";

export class Platform extends Phaser.GameObjects.Zone implements CustomObject {
  public direction: Direction;
  public blockingId: number;
  #triggeredDuringCurrentOverlap = false;

  constructor(scene: Phaser.Scene, config: TiledPlatformObject) {
    super(
      scene,
      config.x + config.width / 2,
      config.y + config.height / 2,
      config.width,
      config.height,
    );

    this.direction = config.direction;
    this.blockingId = config.blockingId;

    scene.add.existing(this);
    scene.physics.add.existing(this, true);

    if (this.body) {
      (this.body as Phaser.Physics.Arcade.Body).setSize(
        config.width,
        config.height,
      );
    }
  }

  public reset(): void {
    this.#triggeredDuringCurrentOverlap = false;
  }

  public enableObject(): void {
    this.active = true;
    this.visible = true;
    if (this.body) {
      (this.body as Phaser.Physics.Arcade.Body).enable = true;
    }
    this.reset();
  }

  public disableObject(): void {
    this.active = false;
    this.visible = false;
    if (this.body) {
      (this.body as Phaser.Physics.Arcade.Body).enable = false;
    }
    this.reset();
  }

  public checkPlayerOverlap(player: Phaser.GameObjects.Sprite): boolean {
    return this.scene.physics.overlap(this, player);
  }

  public shouldTriggerJump(
    player: Phaser.GameObjects.Sprite,
    inputDirection: Direction | null,
  ): boolean {
    const isOverlapping = this.scene.physics.overlap(this, player);

    if (!isOverlapping) {
      this.#triggeredDuringCurrentOverlap = false;
      return false;
    }

    if (this.#triggeredDuringCurrentOverlap) {
      return false;
    }

    if (inputDirection === this.direction) {
      this.#triggeredDuringCurrentOverlap = true;
      return true;
    }

    return false;
  }
}
