import * as Phaser from "phaser";
import { INTERACTIVE_OBJECT_TYPE } from "../../common/constants";
import { getSceneDataManager } from "../../common/data-manager";
import type { TiledMiningObject } from "../../common/tiled/types";
import type { CustomObject } from "../../common/types";
import { InteractiveObjectComponent } from "../../components/interactive-object-component";
import { Effect } from "./effect";

export class MiningSpot
  extends Phaser.GameObjects.Zone
  implements CustomObject
{
  #identifier: number;
  #debugVisual?: Phaser.GameObjects.Rectangle;
  #sparkleEffect?: Effect;

  constructor(
    scene: Phaser.Scene,
    config: TiledMiningObject,
    onInteract: (identifier: number) => void,
  ) {
    super(
      scene,
      config.x + config.width / 2,
      config.y + config.height / 2,
      config.width,
      config.height,
    );

    this.#identifier = config.identifier;

    scene.add.existing(this);
    scene.physics.add.existing(this, true);

    if (this.body) {
      (this.body as Phaser.Physics.Arcade.Body).setSize(
        config.width,
        config.height,
      );
    }

    // Add interactive component for mining
    new InteractiveObjectComponent(
      this,
      INTERACTIVE_OBJECT_TYPE.GAME_HOOK,
      (_heldObject) => {
        onInteract(config.identifier);
        return true;
      },
    );

    // Create sparkle effect (initially disabled)
    this.#sparkleEffect = new Effect(scene, {
      x: this.x - config.width / 2,
      y: this.y - config.height / 2,
      width: config.width,
      height: config.height,
      effect: "sparkle",
    });

    // Start disabled until NPC is talked to
    this.disableObject();
    this.setSparklesEnabled(false);
  }

  get identifier(): number {
    return this.#identifier;
  }

  public enableObject(): void {
    this.active = true;
    this.visible = true;
    if (this.body) {
      (this.body as Phaser.Physics.Arcade.Body).enable = true;
    }
    this.#updateDebugVisual();
  }

  public disableObject(): void {
    this.active = false;
    this.visible = false;
    if (this.body) {
      (this.body as Phaser.Physics.Arcade.Body).enable = false;
    }
    this.#updateDebugVisual();
  }

  #updateDebugVisual(): void {
    if (!this.#debugVisual) {
      return;
    }

    this.#debugVisual.setVisible(this.visible && this.active);
  }

  public setSparklesEnabled(enabled: boolean): void {
    if (this.#sparkleEffect) {
      if (enabled) {
        this.#sparkleEffect.enableObject();
      } else {
        this.#sparkleEffect.disableObject();
      }
    }
  }

  public checkAndUpdateInteractibility(): void {
    const dataManager = getSceneDataManager(this.scene);
    const activeFlag = `mining_${this.#identifier}_active`;
    const talkedFlag = `mining_${this.#identifier}_talked`;
    const gemCollectedFlag = `mining_${this.#identifier}_gem_collected`;
    const isActive = dataManager.hasFrontendFlagValues({
      [activeFlag]: "true",
      [talkedFlag]: "true",
    });
    const gemCollected = dataManager.hasFrontendFlagValues({
      [gemCollectedFlag]: "true",
    });

    // Only enable if active AND gem hasn't been collected yet
    if (isActive && !gemCollected) {
      this.enableObject();
      this.setSparklesEnabled(true);
    } else {
      this.disableObject();
      this.setSparklesEnabled(false);
    }
  }

  public destroy(): void {
    if (this.#debugVisual) {
      this.#debugVisual.destroy();
    }
    if (this.#sparkleEffect) {
      this.#sparkleEffect.destroy();
    }
    super.destroy();
  }
}
