import { GameOverScene } from "../scenes/game-over-scene";
import { MiningMinigameScene } from "../scenes/mining-minigame-scene";
import { SCENE_KEYS } from "../scenes/scene-keys";
import { SerpentineHillsGameScene } from "../scenes/serpentine-hills-game-scene";
import { SerpentineHillsPreloadScene } from "../scenes/serpentine-hills-preload-scene";
import { UIScene } from "../scenes/ui-scene";
import type { SceneLoader } from "./types";

export const loadSerpentineHillsScenes: SceneLoader = (game) => {
  game.scene.add(
    SCENE_KEYS.SERPENTINE_HILLS_PRELOAD_SCENE,
    SerpentineHillsPreloadScene,
    false,
  );
  game.scene.add(
    SCENE_KEYS.SERPENTINE_HILLS_GAME_SCENE,
    SerpentineHillsGameScene,
    false,
  );
  game.scene.add(SCENE_KEYS.UI_SCENE, UIScene, false);
  game.scene.add(SCENE_KEYS.GAME_OVER_SCENE, GameOverScene, false);
  game.scene.add(SCENE_KEYS.MINING_MINIGAME_SCENE, MiningMinigameScene, false);
  game.scene.start(SCENE_KEYS.SERPENTINE_HILLS_PRELOAD_SCENE);
};
