import * as Phaser from "phaser";
import { ASSET_KEYS } from "../../common/assets";
import type { TiledRockObject } from "../../common/tiled/types";
import type { CustomObject } from "../../common/types";

export class Rock extends Phaser.GameObjects.Sprite implements CustomObject {
  #blockingId?: number;
  #hasBeenSteppedOn = false;
  #onStepped?: (blockingId: number, rock: Rock) => void;
  #playerOnRock = false;
  #sinkTimer: Phaser.Time.TimerEvent | null = null;
  #sinking = false;
  #player: Phaser.GameObjects.Sprite | undefined;

  constructor(
    scene: Phaser.Scene,
    config: TiledRockObject,
    onStepped?: (blockingId: number, rock: Rock) => void,
  ) {
    // Create sprite at the position (super must be called first)
    super(
      scene,
      config.x + config.width / 2,
      config.y + config.height / 2,
      ASSET_KEYS.HEBI_ROCK,
      "0",
    );

    scene.add.existing(this);
    scene.physics.add.existing(this, true);

    this.setDepth(1);
    this.#blockingId = config.blockingId;
    this.#onStepped = onStepped;

    if (this.body) {
      (this.body as Phaser.Physics.Arcade.Body).setSize(
        config.width,
        config.height,
      );
      (this.body as Phaser.Physics.Arcade.Body).immovable = true;
    }

    this.enableObject();
  }

  public checkPlayerOverlap(player: Phaser.GameObjects.Sprite): void {
    this.#player = player;
    if (this.#sinking || !this.active) return;

    const isOverlapping = this.scene.physics.overlap(this, player);
    if (isOverlapping && !this.#playerOnRock) {
      this.onPlayerEnter();
    } else if (!isOverlapping && this.#playerOnRock) {
      this.onPlayerExit();
    }
  }

  public onPlayerEnter(): void {
    if (this.#sinking) return;

    this.#playerOnRock = true;
    this.#markStepped();
    this.startSinkTimer();
  }

  public onPlayerExit(): void {
    if (this.#sinking) return;

    this.#playerOnRock = false;
    this.stopSinkTimer();
    this.sinkRock();
  }

  private startSinkTimer(): void {
    if (this.#sinkTimer) {
      this.#sinkTimer.destroy();
    }

    // Start timer
    this.#sinkTimer = this.scene.time.delayedCall(2000, () => {
      // Double check that the player is still overlapping the stone.
      // This is to catch edge cases where the sink timer didn't get stopped.
      if (this.scene.physics.overlap(this, this.#player)) {
        this.sinkRock();
      }
    });
  }

  private stopSinkTimer(): void {
    if (this.#sinkTimer) {
      this.#sinkTimer.destroy();
      this.#sinkTimer = null;
    }
  }

  private sinkRock(): void {
    if (this.#sinking) return;

    this.#sinking = true;

    this.play({
      key: "sinking",
    });
    this.on("animationcomplete", () => {
      // Simple disappear for now (no sinking animation)
      this.disableObject();
      this.#sinking = false;
    });
  }

  public reset(): void {
    this.enableObject();
    this.stopSinkTimer();
    this.#sinking = false;
    this.#playerOnRock = false;
    this.#hasBeenSteppedOn = false;
    this.setFrame("0");
  }

  public enableObject(): void {
    this.active = true;
    this.visible = true;
    if (this.body) {
      (this.body as Phaser.Physics.Arcade.Body).enable = true;
    }
  }

  public disableObject(): void {
    this.active = false;
    this.visible = false;
    if (this.body) {
      (this.body as Phaser.Physics.Arcade.Body).enable = false;
    }
    this.stopSinkTimer();
  }

  get blockingId(): number | undefined {
    return this.#blockingId;
  }

  #markStepped(): void {
    if (this.#hasBeenSteppedOn) {
      return;
    }
    this.#hasBeenSteppedOn = true;
    if (this.#blockingId !== undefined) {
      this.#onStepped?.(this.#blockingId, this);
    }
  }
}
