import * as Phaser from "phaser";
import { DEATH_REASON, DIRECTION } from "../common/constants";
import { CUSTOM_EVENTS, EVENT_BUS } from "../common/event-bus";
import { TILED_LAYER_NAMES } from "../common/tiled/constants";
import {
  getAllLayerNamesWithPrefix,
  getTiledLavaObjectsFromMap,
  getTiledMiningObjectsFromMap,
  getTiledPlatformObjectsFromMap,
  getTiledRockObjectsFromMap,
} from "../common/tiled/utils";
import { type Direction, type InteractiveGameObject } from "../common/types";
import { CHARACTER_STATES } from "../components/state-machine/states/character-states";
import { RockJumpState } from "../components/state-machine/states/rock-jump-state";
import { MiningSpot } from "../entities/objects/mining-spot";
import { Platform } from "../entities/objects/platform";
import { Rock } from "../entities/objects/rock";
import { BaseGameScene } from "./base-game-scene";
import { SCENE_KEYS } from "./scene-keys";

export class SerpentineHillsGameScene extends BaseGameScene {
  private miningSpotsByRoomId = new Map<number, MiningSpot[]>();
  private rocksByRoomId = new Map<number, Rock[]>();
  private rocksByBlockingId = new Map<number, Rock[]>();
  private steppedRocksByBlockingId = new Map<number, Set<Rock | Platform>>();
  private platformsByRoomId = new Map<number, Platform[]>();
  private platformsByBlockingId = new Map<number, Platform[]>();
  private lavaGroup: Phaser.Physics.Arcade.Group | null = null;
  private tutorialCompleted = false;

  constructor() {
    super(SCENE_KEYS.SERPENTINE_HILLS_GAME_SCENE);
  }

  public create(): void {
    super.create();
    this.onEnterRoom(this.currentRoomId);
    this.tutorialCompleted = this.dataManager.hasStoryFlagValues({
      serpentine_mining_quest_2: "completed",
    });
  }

  public startMiningMinigame(miningSpotId: number, gemFrame: string): void {
    this.playerObject.controls.isMovementLocked = true;
    this.scene.launch(SCENE_KEYS.MINING_MINIGAME_SCENE, {
      miningSpotId,
      dataManager: this.dataManager,
      gemFrame,
      keyboard: this.controls,
    });
    this.scene.moveBelow(SCENE_KEYS.UI_SCENE, SCENE_KEYS.MINING_MINIGAME_SCENE);
    EVENT_BUS.once(CUSTOM_EVENTS.MINING_MINI_GAME_COMPLETE, () => {
      this.playerObject.controls.isMovementLocked = false;
    });
  }

  protected override createLevel(): Phaser.Tilemaps.Tilemap | undefined {
    const map = super.createLevel();
    if (map === undefined) {
      return;
    }

    this.createLava(map);
    this.createMiningSpots(map);
    this.createRocks(map);
    this.createPlatforms(map);

    // Check initial mining spot states
    this.updateAllMiningSpots();

    // Listen for frontend flag changes to update mining spot interactibility
    EVENT_BUS.on("FRONTEND_FLAG_CHANGED", () => {
      this.updateAllMiningSpots();
    });

    // Set up cleanup for our custom event listeners
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      EVENT_BUS.off("FRONTEND_FLAG_CHANGED");
    });

    return map;
  }

  private createMiningSpots(map: Phaser.Tilemaps.Tilemap): void {
    const rooms = getAllLayerNamesWithPrefix(map, TILED_LAYER_NAMES.ROOMS).map(
      (layerName: string) => {
        return {
          name: layerName,
          roomId: parseInt(layerName.split("/")[1], 10),
        };
      },
    );
    const miningLayerNames = rooms.filter((layer) =>
      layer.name.endsWith(`/${TILED_LAYER_NAMES.MINING}`),
    );

    miningLayerNames.forEach((layer) => {
      this.createMiningSpotFromLayer(map, layer);
    });
  }

  private createMiningSpotFromLayer(
    map: Phaser.Tilemaps.Tilemap,
    layerName: { name: string; roomId: number },
  ): void {
    const miningSpotsForRoom: MiningSpot[] = [];

    const miningObjects = getTiledMiningObjectsFromMap(map, layerName.name);

    miningObjects.forEach((obj) => {
      const miningSpot = new MiningSpot(this, obj, () => {
        this.startMiningMinigame(obj.identifier, obj.gemFrame);
      });
      miningSpotsForRoom.push(miningSpot);
    });

    this.miningSpotsByRoomId.set(layerName.roomId, miningSpotsForRoom);
  }

  protected appendRoomInteractiveObjects(
    roomId: number,
    objects: InteractiveGameObject[],
  ): void {
    this.miningSpotsByRoomId.get(roomId)?.forEach((spot) => objects.push(spot));
    this.rocksByRoomId.get(roomId)?.forEach((rock) => objects.push(rock));
  }

  private updateAllMiningSpots(): void {
    // Update interactibility for all mining spots
    this.miningSpotsByRoomId.get(this.currentRoomId)?.forEach((miningSpot) => {
      miningSpot.checkAndUpdateInteractibility();
    });
  }
  protected override registerRoundEvents(): void {
    super.registerRoundEvents();

    EVENT_BUS.on(CUSTOM_EVENTS.ROOM_ENTERED, this.onEnterRoom, this);
    this.onEnterRoom(this.currentRoomId);
  }

  protected override unregisterRoundEvents(): void {
    super.unregisterRoundEvents();
    EVENT_BUS.off(CUSTOM_EVENTS.ROOM_ENTERED, this.onEnterRoom, this);
  }

  protected onEnterRoom = (roomId: number): void => {
    const camera = this.cameras.main;
    camera.postFX.clear();

    if (roomId === 1) {
      const colorMatrix: Phaser.Display.ColorMatrix =
        camera.postFX.addColorMatrix();
      colorMatrix.saturate(1.05);
      colorMatrix.contrast(0.1);

      const matrix = colorMatrix.getData();
      matrix[0] *= 1.1;
      matrix[6] *= 1.05;
      matrix[4] += 5;
      colorMatrix.set(matrix);

      camera.postFX.addGlow(0xfff0f0, 1.2, 0.1, false, 0.05, 8);
    }
  };

  private createLava(map: Phaser.Tilemaps.Tilemap): void {
    this.lavaGroup = this.physics.add.group();

    const lavaObjects = getTiledLavaObjectsFromMap(map, TILED_LAYER_NAMES.LAVA);
    lavaObjects.forEach((obj) => {
      // Create invisible zone for collision detection
      const lavaZone = new Phaser.GameObjects.Zone(
        this,
        obj.x + obj.width / 2,
        obj.y + obj.height / 2,
        obj.width,
        obj.height,
      );

      this.add.existing(lavaZone);
      this.physics.world.enable(lavaZone);

      // Make the physics body immovable
      if (lavaZone.body) {
        (lavaZone.body as Phaser.Physics.Arcade.Body).setImmovable(true);
      }

      if (this.lavaGroup) {
        this.lavaGroup.add(lavaZone);
      }
    });
  }

  private createRocks(map: Phaser.Tilemaps.Tilemap): void {
    const rooms = getAllLayerNamesWithPrefix(map, TILED_LAYER_NAMES.ROOMS).map(
      (layerName: string) => {
        return {
          name: layerName,
          roomId: parseInt(layerName.split("/")[1], 10),
        };
      },
    );
    const rockLayerNames = rooms.filter((layer) =>
      layer.name.endsWith(`/${TILED_LAYER_NAMES.ROCKS}`),
    );

    rockLayerNames.forEach((layer) => {
      this.createRocksFromLayer(map, layer);
    });
  }

  private createRocksFromLayer(
    map: Phaser.Tilemaps.Tilemap,
    layerName: { name: string; roomId: number },
  ): void {
    const rocksForRoom: Rock[] = [];

    const rockObjects = getTiledRockObjectsFromMap(map, layerName.name);

    rockObjects.forEach((obj) => {
      const rock = new Rock(this, obj, this.#handleRockStepped);
      rock.enableObject();
      rocksForRoom.push(rock);

      if (obj.blockingId !== undefined) {
        const rocksForBlockingId =
          this.rocksByBlockingId.get(obj.blockingId) ?? [];
        rocksForBlockingId.push(rock);
        this.rocksByBlockingId.set(obj.blockingId, rocksForBlockingId);
      }
    });

    this.rocksByRoomId.set(layerName.roomId, rocksForRoom);
  }

  #handleRockStepped = (blockingId: number, rock: Rock): void => {
    const rocksForBlockingId = this.rocksByBlockingId.get(blockingId);
    if (!rocksForBlockingId?.includes(rock)) {
      return;
    }

    let steppedRocks = this.steppedRocksByBlockingId.get(blockingId);
    if (!steppedRocks) {
      steppedRocks = new Set<Rock>();
      this.steppedRocksByBlockingId.set(blockingId, steppedRocks);
    }

    steppedRocks.add(rock);
  };

  #activateMiningSparkles(blockingId: number): void {
    const miningActiveFlag = `mining_${blockingId}_active`;
    if (
      this.dataManager.hasFrontendFlagValues({ [miningActiveFlag]: "true" })
    ) {
      return;
    }

    this.dataManager.setFrontendFlag(miningActiveFlag, "true");
    this.updateAllMiningSpots();
  }

  #checkBlockingProgress(): void {
    Array.from(this.rocksByBlockingId.entries()).forEach(
      ([blockingId, rocks]) => {
        const steppedRocks = this.steppedRocksByBlockingId.get(blockingId);
        if (!steppedRocks) {
          return;
        }

        const platforms = this.platformsByBlockingId.get(blockingId);

        if (steppedRocks.size === rocks.length + (platforms?.length ?? 0)) {
          this.#activateMiningSparkles(blockingId);
        }
      },
    );
  }

  private createPlatforms(map: Phaser.Tilemaps.Tilemap): void {
    const rooms = getAllLayerNamesWithPrefix(map, TILED_LAYER_NAMES.ROOMS).map(
      (layerName: string) => {
        return {
          name: layerName,
          roomId: parseInt(layerName.split("/")[1], 10),
        };
      },
    );
    const platformLayerNames = rooms.filter((layer) =>
      layer.name.endsWith(`/${TILED_LAYER_NAMES.PLATFORMS}`),
    );

    platformLayerNames.forEach((layer) => {
      this.createPlatformsFromLayer(map, layer);
    });
  }

  private createPlatformsFromLayer(
    map: Phaser.Tilemaps.Tilemap,
    layerName: { name: string; roomId: number },
  ): void {
    const platformsForRoom: Platform[] = [];

    const platformObjects = getTiledPlatformObjectsFromMap(map, layerName.name);

    platformObjects.forEach((obj) => {
      const platform = new Platform(this, obj);
      platform.enableObject();
      platformsForRoom.push(platform);

      if (!this.platformsByBlockingId.has(platform.blockingId)) {
        this.platformsByBlockingId.set(platform.blockingId, []);
      }

      this.platformsByBlockingId.get(platform.blockingId)?.push(platform);
    });

    this.platformsByRoomId.set(layerName.roomId, platformsForRoom);
  }

  protected override onRoundUpdate(): void {
    super.onRoundUpdate();

    // Check rock overlaps in current room
    const currentRoomRocks = this.rocksByRoomId.get(this.currentRoomId);
    if (currentRoomRocks && this.playerObject) {
      currentRoomRocks.forEach((rock) => {
        rock.checkPlayerOverlap(this.playerObject as Phaser.GameObjects.Sprite);
      });
    }

    const currentRoomPlatforms = this.platformsByRoomId.get(this.currentRoomId);
    if (currentRoomPlatforms && this.playerObject) {
      currentRoomPlatforms.forEach((platform) => {
        const overlap = platform.checkPlayerOverlap(
          this.playerObject as Phaser.GameObjects.Sprite,
        );
        if (overlap) {
          if (!this.steppedRocksByBlockingId.has(platform.blockingId)) {
            this.steppedRocksByBlockingId.set(platform.blockingId, new Set());
          }
          this.steppedRocksByBlockingId.get(platform.blockingId)?.add(platform);
        }
      });
    }

    this.#checkBlockingProgress();
    this.#handlePlatformAutoJumps();
  }

  #handlePlatformAutoJumps(): void {
    if (!this.playerObject) {
      return;
    }

    const platforms = this.platformsByRoomId.get(this.currentRoomId);
    if (!platforms || platforms.length === 0) {
      return;
    }

    const inputDirection = this.#getPlayerInputDirection();
    const currentState = this.playerObject.stateMachine.currentState;
    const rockJumpState =
      currentState instanceof RockJumpState ? currentState : null;

    for (const platform of platforms) {
      const shouldJump = platform.shouldTriggerJump(
        this.playerObject as Phaser.GameObjects.Sprite,
        inputDirection,
      );
      if (!shouldJump) {
        continue;
      }

      const origin = { x: platform.x, y: platform.y };
      if (rockJumpState) {
        rockJumpState.startAutoJump(platform.direction, origin);
      } else {
        this.playerObject.stateMachine.setState(
          CHARACTER_STATES.ROCK_JUMP_STATE,
          {
            autoJump: {
              direction: platform.direction,
              origin,
            },
          },
        );
      }

      break;
    }
  }

  #getPlayerInputDirection(): Direction | null {
    const controls = this.playerObject.controls;
    if (controls.isMovementLocked) {
      return null;
    }

    if (controls.isLeftDown) {
      return DIRECTION.LEFT;
    }
    if (controls.isRightDown) {
      return DIRECTION.RIGHT;
    }
    if (controls.isUpDown) {
      return DIRECTION.UP;
    }
    if (controls.isDownDown) {
      return DIRECTION.DOWN;
    }

    return null;
  }

  protected override registerRoundColliders(): void {
    super.registerRoundColliders();

    // Add lava collision that kills the player
    if (this.lavaGroup && this.playerObject) {
      this.physics.add.overlap(this.playerObject, this.lavaGroup, () => {
        const state = this.playerObject.stateMachine.currentState;
        const safe =
          this.playerTouchingRock() ||
          (state instanceof RockJumpState && state.jumping);
        if (safe) {
          return;
        }

        // Player touches lava - instant death
        this.playerObject.setDeathReason(DEATH_REASON.LAVA);
        this.playerObject.hit(DIRECTION.DOWN, 1);
      });
    }
  }

  public playerTouchingRock(): Rock | undefined {
    if (!this.playerObject) {
      return undefined;
    }

    // Check if player is overlapping with any rock in the current room
    const currentRoomRocks = this.rocksByRoomId.get(this.currentRoomId);
    if (!currentRoomRocks) {
      return undefined;
    }

    return currentRoomRocks.filter(
      (rock) => rock.active && this.physics.overlap(this.playerObject, rock),
    )?.[0];
  }

  protected override enableRoomObjects(roomId: number): void {
    super.enableRoomObjects(roomId);
    this.rocksByRoomId.get(roomId)?.forEach((rock) => {
      rock.reset();
    });
    this.platformsByRoomId.get(roomId)?.forEach((platform) => {
      platform.reset();
    });
  }

  protected override resetLevelObjects(): void {
    super.resetLevelObjects();
    // Reset all rocks after death.
    Array.from(this.rocksByRoomId.values()).forEach((rocks) => {
      rocks.forEach((rock) => {
        rock.reset();
      });
    });
    Array.from(this.platformsByRoomId.values()).forEach((platforms) => {
      platforms.forEach((platform) => {
        platform.reset();
      });
    });
    this.steppedRocksByBlockingId.clear();
  }

  protected override refreshLevelObjects(): void {
    super.refreshLevelObjects();
    const newTutorialCompleted = this.dataManager.hasStoryFlagValues({
      serpentine_mining_quest_2: "completed",
    });
    if (!this.tutorialCompleted && newTutorialCompleted) {
      this.rocksByRoomId.get(2)?.forEach((rock) => {
        rock.reset();
      });
    }

    this.tutorialCompleted = newTutorialCompleted;
  }
}
