import IRON_DOOR_PNG from "../assets/images/world_objects/iron_door.png";
import BELL_SOUND from "../assets/sounds/bell.mp3";
import { ASSET_KEYS } from "../common/assets";
import { BasePreloadScene } from "./base-preload-scene";
import { SCENE_KEYS } from "./scene-keys";

export class SerpentineHillsPreloadScene extends BasePreloadScene {
  constructor() {
    super(SCENE_KEYS.SERPENTINE_HILLS_PRELOAD_SCENE);
  }

  public preload(): void {
    super.preload();
    this.#loadSerpentineHillsAssets();
  }

  #loadSerpentineHillsAssets(): void {
    // Load hebi events
    this.load.json(ASSET_KEYS.EVENTS, HEBI_EVENTS);
    this.load.json(ASSET_KEYS.NPCS, HEBI_NPCS);
    this.load.audio(ASSET_KEYS.BELL_SFX, BELL_SOUND);
    this.load.aseprite(ASSET_KEYS.IRON_DOOR, IRON_DOOR_PNG, IRON_DOOR_JSON);

    // Load map.
    this.load.image(ASSET_KEYS.HEBI_BACKGROUND, HEBI_BACKGROUND);
    this.load.image(ASSET_KEYS.HEBI_FOREGROUND, HEBI_FOREGROUND);
    this.load.tilemapTiledJSON(ASSET_KEYS.HEBI_LEVEL, HEBI_LEVEL);

    // Mining game.
    this.load.aseprite(ASSET_KEYS.MINING_CURSOR, CURSOR_PNG, CURSOR_JSON);
    this.load.image(ASSET_KEYS.MINING_BG, MINING_BG);
    this.load.aseprite(ASSET_KEYS.MINING_TILES, TILES_PNG, TILES_JSON);
    this.load.aseprite(
      ASSET_KEYS.MINING_TOOLICONS,
      TOOLICONS_PNG,
      TOOLICONS_JSON,
    );
    this.load.aseprite(ASSET_KEYS.MINING_TOOLS, TOOLS_PNG, TOOLS_JSON);
    this.load.aseprite(ASSET_KEYS.MINING_CRACKS, CRACKS_PNG, CRACKS_JSON);
    this.load.aseprite(ASSET_KEYS.MINING_HITS, HITS_PNG, HITS_JSON);
    this.load.json(ASSET_KEYS.READABLE_MESSAGES, SERPENTINE_HILLS_READABLES);
    this.load.image(ASSET_KEYS.MINING_IRON_0, IRON_0_IMG);
    this.load.image(ASSET_KEYS.MINING_IRON_1, IRON_1_IMG);
    this.load.image(ASSET_KEYS.MINING_IRON_2, IRON_2_IMG);
    this.load.image(ASSET_KEYS.MINING_IRON_3, IRON_3_IMG);
    this.load.image(ASSET_KEYS.MINING_IRON_4, IRON_4_IMG);
    this.load.image(ASSET_KEYS.MINING_IRON_5, IRON_5_IMG);
    this.load.image(ASSET_KEYS.MINING_IRON_6, IRON_6_IMG);
    this.load.image(ASSET_KEYS.MINING_IRON_7, IRON_7_IMG);
    this.load.image(ASSET_KEYS.MINING_IRON_8, IRON_8_IMG);
    this.load.image(ASSET_KEYS.MINING_IRON_9, IRON_9_IMG);
    this.load.image(ASSET_KEYS.MINING_IRON_10, IRON_10_IMG);
    this.load.image(ASSET_KEYS.MINING_IRON_11, IRON_11_IMG);
    this.load.image(ASSET_KEYS.MINING_IRON_12, IRON_12_IMG);
    this.load.image(ASSET_KEYS.MINING_IRON_13, IRON_13_IMG);
    this.load.aseprite(ASSET_KEYS.MINING_GEMS, GEMS_PNG, GEMS_JSON);

    this.load.aseprite(ASSET_KEYS.HEBI_ROCK, ROCK_PNG, ROCK_JSON);

    // NPCs
    this.load.aseprite(ASSET_KEYS.SNAKE_BLUE, SNAKE_BLUE_PNG, SNAKE_BLUE_JSON);
    this.load.aseprite(
      ASSET_KEYS.SNAKE_BROWN,
      SNAKE_BROWN_PNG,
      SNAKE_BROWN_JSON,
    );
    this.load.aseprite(
      ASSET_KEYS.SNAKE_GREEN,
      SNAKE_GREEN_PNG,
      SNAKE_GREEN_JSON,
    );
    this.load.aseprite(ASSET_KEYS.SNAKE_GREY, SNAKE_GREY_PNG, SNAKE_GREY_JSON);
    this.load.aseprite(
      ASSET_KEYS.SNAKE_LIGHT_BLUE,
      SNAKE_LIGHT_BLUE_PNG,
      SNAKE_LIGHT_BLUE_JSON,
    );
    this.load.aseprite(
      ASSET_KEYS.SNAKE_ORANGE_MANE,
      SNAKE_ORANGE_MANE_PNG,
      SNAKE_ORANGE_MANE_JSON,
    );
    this.load.aseprite(
      ASSET_KEYS.SNAKE_ORANGE_PLAIN,
      SNAKE_ORANGE_PLAIN_PNG,
      SNAKE_ORANGE_PLAIN_JSON,
    );
  }

  public create(): void {
    super.create();
    this.#createSerpentineHillsAnimations();
  }

  #createSerpentineHillsAnimations(): void {
    this.anims.createFromAseprite(ASSET_KEYS.HEBI_ROCK);
    this.anims.createFromAseprite(ASSET_KEYS.SNAKE_BLUE);
    this.anims.createFromAseprite(ASSET_KEYS.SNAKE_BROWN);
    this.anims.createFromAseprite(ASSET_KEYS.SNAKE_GREEN);
    this.anims.createFromAseprite(ASSET_KEYS.SNAKE_GREY);
    this.anims.createFromAseprite(ASSET_KEYS.SNAKE_LIGHT_BLUE);
    this.anims.createFromAseprite(ASSET_KEYS.SNAKE_ORANGE_MANE);
    this.anims.createFromAseprite(ASSET_KEYS.SNAKE_ORANGE_PLAIN);
  }
}
