import { type TeamHuntState } from "@hunt/public-client";
import React from "react";
import { hydrateRoot } from "react-dom/client";
import { ErrataDataProvider } from "../../../client/ErrataProvider";
import GameworldZoneClient from "../../../components/overworld/GameworldZoneClient";
import { loadSerpentineHillsScenes } from "../gameworld/scene-loaders/serpentine-hills";
import SerpentineHillsBody from "./SerpentineHillsBody";
import { type SerpentineHillsState } from "./types";

const SerpentineHillsManager = ({
  initialState,
  initialTeamState,
}: {
  initialState: SerpentineHillsState;
  initialTeamState: TeamHuntState;
}) => {
  return (
    <ErrataDataProvider initialTeamState={initialTeamState}>
      <GameworldZoneClient
        roundSlug="serpentine_hills"
        initialState={initialState}
        initialTeamState={initialTeamState}
        sceneLoader={loadSerpentineHillsScenes}
        render={({ state, teamState, gameNode }) => {
          return (
            <SerpentineHillsBody
              state={state}
              teamState={teamState}
              gameNode={gameNode}
            />
          );
        }}
      />
    </ErrataDataProvider>
  );
};

const elem = document.getElementById("serpentine_hills-root");
if (elem) {
  const { initialSerpentineHillsState: state, initialTeamState } =
    window as unknown as {
      initialSerpentineHillsState: SerpentineHillsState;
      initialTeamState: TeamHuntState;
    };
  hydrateRoot(
    elem,
    <SerpentineHillsManager
      initialState={state}
      initialTeamState={initialTeamState}
    />,
  );
} else {
  console.error(
    "Could not mount SerpentineHillsManager because #serpentine_hills-root was nowhere to be found",
  );
}
